using System;
using System.Diagnostics;

// PROGRAM: Simulasi Penalti Latensi Jaringan pada Masalah N+1 Kueri
const int CustomerCount = 50;
const int SimulatedNetworkLatencyMs = 2; // 2 ms per network roundtrip

Console.WriteLine("=== SIMULASI MASALAH KUERI N+1 ===");

// 1. Skenario N+1 (51 Panggilan Network Roundtrip)
var swNPlus1 = Stopwatch.StartNew();
int totalQueryNPlus1 = 1 + CustomerCount; // 1 kueri awal + 50 kueri di loop
int waktuNPlus1 = totalQueryNPlus1 * SimulatedNetworkLatencyMs;
swNPlus1.Stop();
Console.WriteLine($"[N+1 Query Pattern] Jumlah Kueri DB: {totalQueryNPlus1} | Estimasi Waktu Jaringan: {waktuNPlus1} ms");

// 2. Skenario Eager Loading (1 Kueri Tunggal dengan JOIN)
var swEager = Stopwatch.StartNew();
int totalQueryEager = 1; // Tepat 1 kueri SQL
int waktuEager = totalQueryEager * SimulatedNetworkLatencyMs;
swEager.Stop();
Console.WriteLine($"[Eager Loading .Include] Jumlah Kueri DB: {totalQueryEager}  | Estimasi Waktu Jaringan: {waktuEager} ms");

Console.WriteLine($"\nEager loading memangkas latensi sebesar {waktuNPlus1 - waktuEager} ms ({waktuNPlus1 / waktuEager}x lebih cepat)!");

