using System;

public class SqlSargableOptimizer
{
    public static string MakeYearFilterSargable(string columnName, int targetYear)
    {
        if (string.IsNullOrWhiteSpace(columnName) || targetYear <= 0) return "";

        string col = columnName.Trim();
        return $"{col} >= '{targetYear}-01-01' AND {col} < '{targetYear + 1}-01-01'";
    }

    public static void Main()
    {
        Console.WriteLine(MakeYearFilterSargable("CreatedDate", 2026));
    }
}
